DROP TABLE IF EXISTS `daily_institutional_trading`;
CREATE TABLE IF NOT EXISTS `daily_institutional_trading` (
  `stock_id` varchar(20) NOT NULL COMMENT '股票代號',
  `trade_date` date NOT NULL COMMENT '交易日期',
  `foreign_vol` int(11) DEFAULT 0 COMMENT '外資買賣超(張)',
  `trust_vol` int(11) DEFAULT 0 COMMENT '投信買賣超(張)',
  `dealer_vol` int(11) DEFAULT 0 COMMENT '自營商買賣超(張)',
  `total_vol` int(11) DEFAULT 0 COMMENT '合計買賣超(張)',
  `foreign_ratio` decimal(10,2) DEFAULT 0.00 COMMENT '外資籌碼(%)',
  `price_change_pct` decimal(10,2) DEFAULT 0.00 COMMENT '漲跌幅(%)',
  `volume` int(11) DEFAULT 0 COMMENT '成交量',
  `margin_balance` int(11) DEFAULT 0 COMMENT '融資餘額',
  `short_balance` int(11) DEFAULT 0 COMMENT '融券餘額',
  `lending_balance` int(11) DEFAULT 0 COMMENT '借券賣出餘額',
  PRIMARY KEY (`stock_id`,`trade_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

